// Emit Zig Unicode uppercase mappings matching the JS reference engine.
// Regeneration: run with Node and use the emitted text for src/cfb/uppercase.zig.
console.log(
  "// Generated by tools/generate-uppercase.mjs; Node Unicode " +
    process.versions.unicode +
    ".",
);
console.log("pub fn mapping(cp: u21) ?[]const u8 { return switch (cp) {");
for (let cp = 0; cp <= 0x10ffff; cp++) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  const text = String.fromCodePoint(cp),
    upper = text.toUpperCase();
  if (text !== upper)
    console.log("0x" + cp.toString(16) + " => " + JSON.stringify(upper) + ",");
}
console.log("else => null, }; }");
